export const proficiencyPerkDefinitions = deepFreeze<ProficiencyPerkDefinition[]>([...swordPerks, ...firePerks, ...wardPerks, ...disruptPerks])

for (const proficiencyId of [...new Set(proficiencyPerkDefinitions.map((perk) => perk.proficiencyId))]) assertValidPerkGraph(proficiencyPerkDefinitions, proficiencyId)

// Compatibility aliases keep old V2 callers and saves readable while the authored V3 trees use their new graph IDs.
const legacyFor = (proficiencyId: CombatProficiencyId, slug: string, name: string, requiredProficiencyLevel: number, maxRank: number, effects: ProficiencyPerkEffect[], prerequisiteRules: PerkPrerequisiteRule[] = []): ProficiencyPerkDefinition => ({ id: id(proficiencyId, slug), proficiencyId, branch: 'Legacy', name, requiredProficiencyLevel, maxRank, costPerRank: 1, description: 'Legacy compatibility alias.', effects, prerequisiteRules, presentation: pos(4, 0), autoGranted: false })
const legacy = (slug: string, name: string, requiredProficiencyLevel: number, maxRank: number, effects: ProficiencyPerkEffect[], prerequisiteRules: PerkPrerequisiteRule[] = []) => legacyFor(sword, slug, name, requiredProficiencyLevel, maxRank, effects, prerequisiteRules)
